#define _XOPEN_SOURCE 700

#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "msg.h"
#include "util.h"

static void out_of_memory(void)
{
	msg_error("error.nomem");
	exit(1);
}

void *xmalloc(size_t size)
{
	void *p;

	p = malloc(size ? size : 1);
	if (p == NULL)
		out_of_memory();
	return p;
}

void *xrealloc(void *ptr, size_t size)
{
	void *p;

	p = realloc(ptr, size ? size : 1);
	if (p == NULL)
		out_of_memory();
	return p;
}

char *xstrdup(const char *s)
{
	size_t n;

	n = strlen(s) + 1;
	return memcpy(xmalloc(n), s, n);
}

/* Joins with exactly one slash between the parts, so "/" + "a" gives "/a". */
char *xjoin(const char *dir, const char *name)
{
	size_t d, n;
	char *p;

	d = strlen(dir);
	while (d > 0 && dir[d - 1] == '/')
		d--;
	while (*name == '/')
		name++;
	n = strlen(name);
	p = xmalloc(d + n + 2);
	memcpy(p, dir, d);
	p[d] = '/';
	memcpy(p + d + 1, name, n + 1);
	return p;
}

/* POSIX leaves getcwd(NULL, 0) unspecified, so the buffer grows by hand. */
char *xgetcwd(void)
{
	size_t size;
	char *buf;

	for (size = 256;; size *= 2) {
		buf = xmalloc(size);
		if (getcwd(buf, size) != NULL)
			return buf;
		free(buf);
		if (errno != ERANGE)
			return NULL;
	}
}
